module TopModule (
  input in,
  input [3:0] state,
  output reg [3:0] next_state,
  output out
);
reg [3:0] state_one_hot;
  assign state_one_hot = {4{1'b0}};
  assign state_one_hot[state] = 1'b1;
  always @* begin
    case (state_one_hot)
      4'b0001: begin
        next_state = in ? 4'b0010 : 4'b0001;
      end
      4'b0010: begin
        next_state = in ? 4'b0100 : 4'b0010;
      end
      4'b0100: begin
        next_state = in ? 4'b1000 : 4'b0100;
      end
      4'b1000: begin
        next_state = in ? 4'b0001 : 4'b1000;
      end
      default: begin
        next_state = 4'b0000;
      end
    endcase
  end
  assign out = state_one_hot == 4'b1000 ? 1'b1 : 1'b0;
endmodule

