      default: next_in = 0;
    endcase
  end
  always @(state, in) begin
    case (state)
      B: begin
        if (in)
          next_out = 1;
        else
          next_out = 0;
      end
      A: begin
        if (in)
          next_out = 0;
        else
          next_out = 0;
      end
      default: next_out = 0;
    endcase
  end
  always @(posedge clk) begin
    if (reset) begin
      next_reset = 1;
    end else begin
      next_reset = 0;
    end
  end
  always @(posedge clk) begin
    if (reset) begin
      next_state = B;
    end else begin
      next_state = state;
