  assign B3_next = next_state[9];
  assign S_next = next_state[8];
  assign S1_next = next_state[7];
  assign Count_next = next_state[6];
  assign Wait_next = next_state[5];
  assign done = next_state[4];
  assign counting = next_state[3];
  assign shift_ena = next_state[2];

  always @* begin
    next_state = state;
    if (d == 1'b0) begin
      next_state = S;
    end else begin
      next_state = S1;
    end
    if (done_counting == 1'b0) begin
      next_state = B0;
    end else begin
      next_state = B1;
    end
    if (ack == 1'b0) begin
      next_state = B2;
    end else begin
      next_state = B3;
    end
    if (next_state == B3) begin
      next_state = Count;
    end
    if (next_state == Count) begin
      next_state = Wait;
    end
    if (next_state == Wait) begin
      next_state = S;
    end
  end
endmodule

