        if (bump_left) begin
          next_state = 2'b00;
        end
        else if (bump_right) begin
          next_state = 2'b10;
        end
        else if (ground == 0) begin
          next_state = 2'b10;
        end
        else if (dig) begin
          next_state = 2'b10;
        end
