module rtcl_p3s7_blinking_led
        #(
            parameter   int COUNT_LIMIT = 50_000_000
        )
        (
            input   var logic           clk50   ,
            input   var logic           clk72   ,
            output  var logic   [1:0]   led     ,
            output  var logic   [7:0]   pmod    
        );
logic   [31:0]  counter50;
    logic   [31:0]  counter72;

    always_ff @(posedge clk50)
    begin
        if (counter50 == COUNT_LIMIT)
        begin
            counter50 <= 0;
        end
        else
        begin
            counter50 <= counter50 + 1;
        end
    end

    always_ff @(posedge clk72)
    begin
        if (counter72 == COUNT_LIMIT)
        begin
            counter72 <= 0;
        end
        else
        begin
            counter72 <= counter72 + 1;
        end
    end

    assign led = { counter50[31], counter50[30] };
    assign pmod = { counter72[7:0], counter72[7:0] };

endmodule

