module eb1_5 #(
	parameter WIDTH = 8,
	parameter S0 = 3'o0,
	parameter S1 = 3'o1,
	parameter S2 = 3'o2,
	parameter S3 = 3'o3,
	parameter S4 = 3'o4
) (
	input  clk, reset_n,
	input         [WIDTH-1:0] t0_data,
	input                     t0_valid,
	output logic              t0_ready,
	output logic  [WIDTH-1:0] i0_data,
	output logic              i0_valid,
	input                     i0_ready
);
logic  [WIDTH-1:0] dat0, dat1;
	logic              valid0, valid1;
	logic  [1:0] state, next_state;

	always_ff @(posedge clk) begin
		if (!reset_n) begin
			state <= S0;
		end else begin
			state <= next_state;
		end
	end

	always_comb begin
		next_state = state;
		i0_data = 0;
		i0_valid = 0;
		t0_ready = 0;
		valid0 = 0;
		valid1 = 0;

		case (state)
			S0: begin
				if (t0_valid & i0_ready) begin
					next_state = S1;
					valid0 = 1;
				end
			end
			S1: begin
				if (t0_valid & i0_ready) begin
					next_state = S2;
					valid0 = 1;
				end else if (i0_ready) begin
					next_state = S0;
					valid0 = 0;
				end
			end
			S2: begin
				if (t0_valid & i0_ready) begin
					next_state = S3;
					valid0 = 1;
				end else if (i0_ready) begin
					next_state = S0;
					valid0 = 0;
				end
			end
			S3: begin
				if (t0_valid & i0_ready) begin
					next_state = S4;
					valid0 = 1;
				end else if (i0_ready) begin
					next_state = S0;
					valid0 = 0;
				end
			end
			S4: begin
				if (t0_valid & i0_ready) begin
					next_state = S1;
					valid0 = 1;
				end else if (i0_ready) begin
					next_state = S0;
					valid0 = 0;
				end
			end
			default: next_state = S0;
		endcase
	end

endmodule

module fifo_simple
#(
    parameter               WIDTH=16,
    parameter               DEPTH=16,
    parameter               PROG_FULL=14
)    
(
    input   wire                    reset_p,    
    input   wire                    clk,        

    input   wire    [WIDTH-1:0]     data_i,
    input   wire                    data_we,

    output  wire    [WIDTH-1:0]     data_o,
    input   wire                    data_rd,

    output  wire                    prog_full,
    output  wire                    full,
    output  wire                    empty,
    output  reg                     overflow,
    output  reg                     underflow

);
reg [WIDTH-1:0] mem [0:DEPTH-1];
reg [WIDTH-1:0] wcount;
reg [WIDTH-1:0] rcount;
reg [WIDTH-1:0] full;
reg [WIDTH-1:0] empty;

assign data_o = mem[rcount];

assign full = (wcount == DEPTH-1) ? 1'b1 : 1'b0;
assign empty = (rcount == 0) ? 1'b1 : 1'b0;
assign prog_full = (wcount >= PROG_FULL) ? 1'b1 : 1'b0;

always @(posedge clk) begin
    if (reset_p) begin
        wcount <= 0;
        rcount <= 0;
        full <= 0;
        empty <= 1;
        overflow <= 0;
        underflow <= 0;
    end else begin
        if (data_we && !full) begin
            mem[wcount] <= data_i;
            wcount <= wcount + 1;
            full <= 1;
            underflow <= 0;
        end
        if (data_rd && !empty) begin
            mem[rcount] <= data_i;
            rcount <= rcount + 1;
            empty <= 1;
            overflow <= 0;
        end
        if (data_we && full) begin
            wcount <= wcount - 1;
            full <= 0;
            overflow <= 0;
        end
        if (data_rd && empty) begin
            rcount <= rcount - 1;
            empty <= 0;
            underflow <= 0;
        end
    end
end

endmodule

