	);
assign OUT[0] = (IN[0] & IN[1]) | (IN[0] & IN[2]) | (IN[1] & IN[2]) | (IN[0] & IN[1] & IN[2]);
	assign OUT[1] = IN[0] ^ IN[1] ^ IN[2] ^ IN[3];
	assign OUT[2] = IN[1];
	assign OUT[3] = IN[0];
endmodule

