    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);
localparam IDLE = 0, DATA0 = 1, DATA1 = 2;
   reg [1:0] state, next_state;
   assign dst_rdy_o = (state == DATA0 && dst0_rdy_i) ||
                      (state == DATA1 && dst1_rdy_i);
   assign src0_rdy_o = (state == DATA0 && src_rdy_i) ||
                       (state == DATA1 && dst1_rdy_i);
   assign src1_rdy_o = (state == DATA1 && src_rdy_i) ||
                       (state == DATA0 && dst0_rdy_i);
   assign data0_o = (state == DATA0) ? data_i : 0;
   assign data1_o = (state == DATA1) ? data_i : 0;
   always @(posedge clk) begin
      if (reset) begin
         state <= IDLE;
      end else begin
         state <= next_state;
      end
   end
   always @(*) begin
      next_state = state;
      case (state)
         IDLE: begin
            if (src_rdy_i) begin
               next_state = DATA0;
            end
         end
         DATA0: begin
            if (src_rdy_i) begin
               next_state = DATA1;
            end else if (dst0_rdy_i) begin
               next_state = IDLE;
            end
         end
         DATA1: begin
            if (src_rdy_i) begin
               next_state = DATA0;
            end else if (dst1_rdy_i) begin
               next_state = IDLE;
            end
         end
      endcase
   end
