module sqrt_pipelined
  #(
    parameter
    INPUT_BITS   = 16, 
    OUTPUT_BITS  = INPUT_BITS / 2 + INPUT_BITS % 2 
    )
  (
   input                        clk,        
   input                        reset_n,    
   input                        start,      
   input [INPUT_BITS-1:0]       radicand,   
   output reg                   data_valid, 
   output reg [OUTPUT_BITS-1:0] root        
   );
reg [INPUT_BITS-1:0] start_gen;
   reg [INPUT_BITS-1:0] radicand_gen;
   reg [INPUT_BITS-1:0] root_gen;
   reg [INPUT_BITS-1:0] mask_gen;

   always @ (posedge clk or negedge reset_n)
     if (!reset_n)
       begin
         start_gen <= 0;
         radicand_gen <= 0;
         root_gen <= 0;
         mask_gen <= 0;
       end
     else
       begin
         start_gen <= start;
         radicand_gen <= radicand;
         root_gen <= root;
         mask_gen <= mask_gen + 1;
       end

   genvar i;
   generate for (i=0; i<OUTPUT_BITS; i=i+1)
     begin: stage
        always @ (posedge clk or negedge reset_n)
          if (!reset_n)
            begin
              root_gen[i] <= 0;
              data_valid <= 0;
            end
          else
            begin
              root_gen[i] <= root_gen[i] + (mask_gen[i] & (radicand_gen[i] - root_gen[i] * root_gen[i]));
              data_valid <= 0;
            end
     end
   endgenerate

   always @ (posedge clk or negedge reset_n)
     if (!reset_n)
       root <= 0;
     else
       root <= root_gen[OUTPUT_BITS-1];

endmodule

