module ps2controller (
    input reset,
    input i_clock,
    input i_data,
    output scan_ready,
    output [7:0] scan_code
);
reg [7:0] scan_code_reg;
    reg [3:0] counter;
    reg ready;
    always @(negedge i_clock) begin
        if (reset) begin
            scan_code_reg <= 8'b0;
            counter <= 4'b0;
            ready <= 1'b0;
        end else begin
            if (counter == 4'b1111) begin
                ready <= 1'b0;
            end else begin
                ready <= 1'b1;
            end
            if (i_data) begin
                scan_code_reg[counter] <= 1'b1;
                counter <= counter + 1'b1;
            end else begin
                scan_code_reg[counter] <= 1'b0;
                counter <= counter + 1'b1;
            end
            if (counter == 4'b1111) begin
                if (scan_code_reg[8] == 1'b1) begin
                    ready <= 1'b0;
                end else begin
                    ready <= 1'b1;
                end
            end
            if (counter == 4'b1111) begin
                if (i_data) begin
                    scan_code_reg[9] <= 1'b1;
                    counter <= 4'b0;
                end else begin
                    scan_code_reg[9] <= 1'b0;
                    counter <= 4'b0;
                end
            end
        end
    end
    assign scan_code = scan_code_reg;
    assign scan_ready = ready;
endmodule

