module Math_Divide(
	input CLK, 
	input [31:0] Divisor, 
	input [31:0] Divider,
	output [31:0] result, 
	output [31:0] remainder,
	inout done 
    );
reg [31:0] divisor;
	reg [31:0] divider;
	reg [31:0] remainder;
	reg [31:0] result;
	reg [31:0] counter;
	
	always @(posedge CLK) begin
		if (Divisor != 0 && Divider != 0) begin
			if (Divisor > 32'd1) begin
				if (Divisor > 32'd100000000) begin
					remainder <= 32'd0;
					result <= 32'd0;
					counter <= 32'd0;
				end else begin
					if (Divisor > 32'd1000000) begin
						remainder <= 32'd0;
						result <= 32'd0;
						counter <= 32'd0;
					end else begin
						if (Divisor > 32'd100000) begin
							remainder <= 32'd0;
							result <= 32'd0;
							counter <= 32'd0;
						end else begin
							if (Divisor > 32'd10000) begin
								remainder <= 32'd0;
								result <= 32'd0;
								counter <= 32'd0;
							end else begin
								if (Divisor > 32'd1000) begin
									remainder <= 32'd0;
									result <= 32'd0;
									counter <= 32'd0;
								end else begin
									if (Divisor > 32'd100) begin
										remainder <= 32'd0;
										result <= 32'd0;
										counter <= 32'd0;
									end else begin
										if (Divisor > 32'd10) begin
											remainder <= 32'd0;
											result <= 32'd0;
											counter <= 32'd0;
										end else begin
											if (Divisor > 32'd1) begin
												remainder <= 32'd0;
												result <= 32'd0;
												counter <= 32'd0;
											end else begin
												if (Divisor > 32'd0) begin
													remainder <= 32'd0;
													result <= 32'd0;
													counter <= 32'd0;
												end else begin
													remainder <= 32'd0;
													result <= 32'd0;
													counter <= 32'd0;
												end
											end
										end
									end
								end
							end
						end
					end
				end
			end else begin
				remainder <= 32'd0;
				result <= 32'd0;
				counter <= 32'd0;
			end
		end else begin
			remainder <= 32'd0;
			result <= 32'd0;
			counter <= 32'd0;
		end
	end
	
