module stallmem (DataOut, Done, Stall, CacheHit, err, Addr, DataIn, Rd, Wr, createdump, clk, rst);

   output  [15:0] DataOut;
   output         Done;
   output         Stall;
   output         CacheHit;
   input [15:0]   DataIn;
   input [15:0]   Addr;
   input          Wr;
   input          Rd;
   input          createdump;
   input          clk;
   input          rst;
   output         err;
reg [15:0]      DataOut;
   reg             Done;
   reg             err;
   reg [15:0]      largest;
   reg [31:0]      rand_pat;
   reg             ready;
   reg             loaded;
   reg [15:0]      mem [0:63];
   wire             muxSel;
   wire             ready;

   assign muxSel = (ready) ? ~Wr : Rd;
   assign DataOut = (err) ? mem[Addr[15:0]] : DataIn;
   assign Done = ready;
   assign Stall = ~ready;
   assign CacheHit = 1'b0;

   initial begin
      loaded = 1'b0;
      largest = 16'h0000;
      rand_pat = 32'h00000000;
      ready = 1'b0;
      err = 1'b0;
   end

   always @(posedge clk) begin
      if (rst) begin
         rand_pat <= 32'h00000000;
         ready <= 1'b0;
         err <= 1'b0;
      end else begin
         rand_pat <= {rand_pat[30:0], rand_pat[31]};
         if (muxSel) begin
            if (Wr) begin
               mem[Addr[15:0]] <= DataIn;
               largest <= Addr[15:0];
            end
            if (ready) begin
               if (rand_pat[0]) begin
                  err <= 1'b1;
                  ready <= 1'b0;
               end else begin
                  err <= 1'b0;
                  ready <= 1'b1;
               end
            end
         end
         #1 rand_pat <= {rand_pat[30:0], rand_pat[31]};
      end
   end

endmodule

module pwm(
input wire clk,
input wire rst,
input wire [31:0] duty,
output reg pwm_out
); 

parameter PERIOD = 8;
reg [31:0] duty_reg;
reg [31:0] counter;
  always @(posedge clk, posedge rst) begin
    if(rst == 1'b1) begin
      duty_reg <= duty;
      counter <= 0;
      pwm_out <= 1'b0;
    end else begin
      if(counter < duty_reg) begin
        pwm_out <= 1'b1;
      end
      else begin
        pwm_out <= 1'b0;
      end
      if(counter == (PERIOD - 1)) begin
        counter <= 0;
        duty_reg <= duty;
      end
      else begin
        counter <= counter + 1;
      end
    end
  end
endmodule

