module pipelined_multiplier (a, b, clk, pdt);
input [size-1 : 0] a;
input [size-1 : 0] b;
input clk;
output [2*size-1 : 0] pdt;
parameter size = 16;
parameter level = 2;

reg [size-1 : 0] a_int;
reg [size-1 : 0] b_int;
reg [2*size-1 : 0] pdt_int [0 : level-1];

always @(posedge clk)
begin
    a_int <= a;
    b_int <= b;
    pdt_int[0] <= a_int * b_int;
    for (int i = 1; i < level; i = i + 1)
    begin
        pdt_int[i] <= pdt_int[i-1];
    end
end

assign pdt = pdt_int[level-1];

endmodule

