module dff16_SyncReset (clock, CE, d, q, reset);
	input clock;
	input CE;
	input [15:0] d;
	input reset;
	output reg [15:0] q;
always @ (posedge clock)
	begin
		if (reset == 0)
			q <= 0;
		else if (CE == 1)
			q <= d;
	end
endmodule

