module bcd(
input wire clk,
input wire clr,
input wire ce,
output wire [3:0] q
); 

reg [3:0] dint;
reg [3:0] qreg;
  always @(posedge clk, posedge clr) begin
    if(clr == 1'b1) begin
      qreg <= {4{1'b0}};
    end else begin
      if(ce == 1'b1) begin
        if(dint == 4'b1001) begin
          dint <= {4{1'b0}};
        end
        else begin
          dint <= dint + 1;
        end
      end
    end
  end
  always @(posedge clk) begin
    dint <= dint + 1;
  end
  assign q = qreg;
endmodule

module table_010001010(input clk, input rst, input [10:0] addr, output reg match);
always@(posedge clk) begin
    casex (addr)
      11'b00010000100: match <= 1'b1;
      11'b00010000110: match <= 1'b1;
      default: match <= 1'b0;
    endcase

    if(rst)
      match <= 1'b0;
  end
endmodule

module Control(
   
	input wire clk,rst,
	input [7:0] in3,in2,in1,in0,
	output reg [3:0] anodo,
	output reg [7:0] catodo
    );
localparam N = 18;
	reg [N-1:0] q_reg;
	
	always @(posedge clk or posedge rst)
	begin
		if(rst) q_reg <= 0;
		else q_reg <= q_reg + 1;
	end
	
	assign anodo = q_reg[17:16];
	assign catodo = q_reg[15:8];
	
endmodule

