module ASYNC_ROM(q, addr);

  input  [AWIDTH-1:0] addr; 
  output [DWIDTH-1:0] q;
parameter DWIDTH = 8;
  parameter AWIDTH = 10;
  parameter DEPTH = 2**AWIDTH;

  reg [DWIDTH-1:0] mem [0:DEPTH-1];

  assign q = mem[addr];

  initial begin
    if (MIF_HEX != "") begin
      $readmemh(MIF_HEX, mem);
    end else if (MIF_BIN != "") begin
      $readmemh(MIF_BIN, mem);
    end else begin
      $display("Initializing with all-zero memory");
      $readmemh("0", mem);
    end
  end

endmodule

