module ALU(
    input [31:0] a,
    input [31:0] b,
    input [3:0] control,
    output reg [31:0] result,
    output zero
);
always @* begin
        case (control)
            4'b0000: result = a + b;
            4'b0001: result = a - b;
            4'b0010: result = a & b;
            4'b0011: result = a | b;
            4'b0100: result = ~(a | b);
            4'b0101: result = a ^ b;
            4'b0110: result = (a == b) ? 32'b1 : 32'b0;
            4'b0111: result = a >> b;
            4'b1000: result = a << b;
            default: result = a + b;
        endcase
    end
    assign zero = result == 0 ? 1 : 0;
endmodule

module flag(

	input [2:0]sign,
	input islow,
	input carry_in,


	output reg carry_out,
	output reg led2
);
reg regcarry;

	always @(*)
	begin
		if (islow == 1'b1)
		begin
			regcarry <= carry_in;
			carry_out <= 1'b0;
		end
		else
		begin
			carry_out <= regcarry;
		end
	end

	always @(*)
	begin
		if (islow == 1'b1)
		begin
			led2 <= (carry_out == 1'b0) && (sign == 1'b0);
		end
		else
		begin
			led2 <= (carry_out == 1'b0) && (sign == 1'b1);
		end
	end

endmodule

