module shift #(
    parameter DATA_WIDTH = 16,
    parameter DATA_TYPE = "unsigned", 
    parameter SHIFT_VALUE = 1,      
    parameter ASYNC = 0,             
    parameter OVERFLOW_WARNING = 1
) (
    input wire clk,
    input wire [DATA_WIDTH-1:0] din,

    output wire [DATA_WIDTH-1:0] dout,
    output wire [1:0] warning
);
reg [DATA_WIDTH-1:0] shift_reg;
wire [DATA_WIDTH-1:0] shift_out;

assign shift_out = (DATA_TYPE == "signed") ? (din[DATA_WIDTH-1] ? din - (1 << (DATA_WIDTH-1)) : din + (1 << (DATA_WIDTH-1))) : din >> SHIFT_VALUE;

assign dout = shift_out;
assign warning = (DATA_TYPE == "signed") ? (shift_out[DATA_WIDTH-1] ? {1'b1, 1'b0} : {1'b0, 1'b0}) : (shift_out[DATA_WIDTH-1] ? {1'b1, 1'b0} : {1'b0, 1'b0});

generate
    if (ASYNC == 0) begin
        always @(posedge clk) begin
            shift_reg <= shift_out;
        end
    end else begin
        assign shift_reg = shift_out;
    end
endgenerate

endmodule

