module diffeq_f_systemC(aport, dxport, xport, yport, uport, clk, reset);

input clk;
input reset;
input [31:0]aport;
input [31:0]dxport;
output [31:0]xport;
output [31:0]yport;
output [31:0]uport;
reg [31:0]xport;
reg [31:0]yport;
reg [31:0]uport;

always @(posedge clk)
begin
	if(reset)
	begin
		xport <= 0;
		yport <= 0;
		uport <= 0;
	end
	else
	begin
		xport <= (aport + dxport) - (xport + yport);
		yport <= (aport + dxport) - (yport + uport);
		uport <= (aport + dxport) - (uport + xport);
	end
end

endmodule

