reg [15:0] height_reg;
reg [15:0] width_reg;

wire [23:0] allowed_cycles_next;
wire [15:0] height_next;
wire [15:0] width_next;

assign allowed_cycles_next = (full_rst) ? 24'h65b710 : allowed_cycles_reg;
assign height_next = (full_rst) ? 16'h0c00 : height_reg;
assign width_next = (full_rst) ? 16'h1000 : width_reg;

always @(posedge full_clk) begin
    allowed_cycles_reg <= allowed_cycles_next;
