module UP_COUNTER #( parameter INIT_VALUE = 4'b0) (
	input wire       Reset,
	input wire       clock,
	output reg [3:0] Q
);
initial Q = INIT_VALUE;
	always @(posedge clock) begin
		if (Reset) begin
			Q <= INIT_VALUE;
		end else begin
			Q <= Q + 1;
		end
	end
endmodule

