module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
reg [BITS - 1:0] cnt;
    wire [BITS - 1:0] enable_wires;
    assign enable_wires[0] = ena;
    genvar i;
    generate for (i = 0; i < BITS; i = i + 1) begin
        always @(posedge clk, posedge rst) begin
            if (rst) begin
                cnt[i] <= 1'b0;
            end else if (enable_wires[i]) begin
                if (updown) begin
                    cnt[i] <= cnt[i] + 1;
                end else begin
                    cnt[i] <= cnt[i] - 1;
                end
            end
        end
    end
    endgenerate
    assign out = cnt;
    assign ovf = (cnt == 2**BITS - 1) || (cnt == 0);
endmodule

