module wb_bridge_16_32
  #(parameter AWIDTH=16)
    (input wb_clk, input wb_rst,
     input A_cyc_i, input A_stb_i, input A_we_i, input [3:0] A_sel_i,
     input [AWIDTH-1:0] A_adr_i, input [31:0] A_dat_i, output [31:0] A_dat_o, output A_ack_o,
     output B_cyc_o, output B_stb_o, output B_we_o, output [1:0] B_sel_o,
     output [AWIDTH-1:0] B_adr_o, output [15:0] B_dat_o, input [15:0] B_dat_i, input B_ack_i
     );
reg [15:0] phase;
   reg [31:0] hold;
   assign A_dat_o = (phase == 0) ? A_dat_i[31:16] : A_dat_i[15:0];
   assign B_adr_o = (phase == 0) ? A_adr_i[AWIDTH-1:16] : A_adr_i[15:0];
   assign B_sel_o = (phase == 0) ? A_sel_i : 2'b00;
   assign B_cyc_o = A_cyc_i;
   assign B_stb_o = A_stb_i;
   assign B_we_o = A_we_i;
   assign A_ack_o = B_ack_i;
   always @(posedge wb_clk) begin
      if (wb_rst) begin
         phase <= 0;
         hold <= 0;
      end else begin
         if (A_cyc_i && A_stb_i && A_we_i) begin
            if (phase == 0) begin
               hold <= A_dat_i[31:16];
               phase <= 1;
            end else begin
               hold <= A_dat_i[15:0];
               phase <= 0;
            end
         end
         if (B_cyc_o && B_stb_o && B_we_o) begin
            if (phase == 0) begin
               hold <= B_dat_i[31:16];
               phase <= 1;
            end else begin
               hold <= B_dat_i[15:0];
               phase <= 0;
            end
         end
      end
   end
endmodule

