module IB_ENDPOINT_OP_DONE_BUFFER(
input wire CLK,
input wire RESET,
input wire [15:0] RD_COMPL_TAG,
input wire RD_COMPL_START,
input wire RD_COMPL_DONE,
input wire [15:0] BM_TAG,
input wire BM_DONE,
output wire [15:0] OP_TAG,
output wire OP_DONE
); 

reg [15:0] tag;
reg read_compl_start;
reg bm_tag_valid;
reg bm_tag_done;
  always @(posedge CLK, posedge RESET) begin
    if(RESET == 1'b1) begin
      tag <= {16{1'b0}};
      read_compl_start <= 1'b0;
      bm_tag_valid <= 1'b0;
      bm_tag_done <= 1'b0;
    end else begin
      if(RD_COMPL_START == 1'b1) begin
        tag <= RD_COMPL_TAG;
        read_compl_start <= 1'b1;
        bm_tag_valid <= 1'b0;
        bm_tag_done <= 1'b0;
      end
      else if(RD_COMPL_DONE == 1'b1) begin
        tag <= {16{1'b0}};
        read_compl_start <= 1'b0;
        bm_tag_valid <= 1'b0;
        bm_tag_done <= 1'b0;
      end
      else if(BM_DONE == 1'b1) begin
        tag <= BM_TAG;
        bm_tag_valid <= 1'b1;
        bm_tag_done <= 1'b1;
      end
      else begin
        tag <= {16{1'b0}};
        read_compl_start <= 1'b0;
        bm_tag_valid <= 1'b0;
        bm_tag_done <= 1'b0;
      end
    end
  end
  assign OP_DONE = bm_tag_done == 1'b1 ? 1'b1 : 1'b0;
  assign OP_TAG = read_compl_start == 1'b1 ? tag : BM_TAG;
endmodule

