module syn_gen
(
    input              I_pxl_clk   ,
    input              I_rst_n     ,
    input      [15:0]  I_h_total   ,
    input      [15:0]  I_h_sync    ,
    input      [15:0]  I_h_bporch  ,
    input      [15:0]  I_h_res     ,
    input      [15:0]  I_v_total   ,
    input      [15:0]  I_v_sync    ,
    input      [15:0]  I_v_bporch  ,
    input      [15:0]  I_v_res     ,
    input      [15:0]  I_rd_hres   ,
    input      [15:0]  I_rd_vres   ,
    input              I_hs_pol    ,
    input              I_vs_pol    ,
    output reg         O_rden      ,
    output reg         O_de        ,   
    output reg         O_hs        ,
    output reg         O_vs         
);
reg [15:0] V_cnt;
    reg [15:0] H_cnt;
    reg [15:0] Pout_de_w;
    reg [15:0] Pout_hs_w;
    reg [15:0] Pout_vs_w;
    reg [15:0] Rden_w;
    always @(posedge I_pxl_clk or negedge I_rst_n)
    begin
        if (!I_rst_n)
        begin
            V_cnt <= 0;
            H_cnt <= 0;
        end
        else
        begin
            if (V_cnt == I_v_total - 1)
            begin
                V_cnt <= 0;
                H_cnt <= H_cnt + 1;
            end
            else
            begin
                V_cnt <= V_cnt + 1;
            end
        end
    end
    always @*
    begin
        Pout_de_w = (H_cnt >= I_h_sync && H_cnt < I_h_sync + I_h_res) ? 16'b1 : 16'b0;
        Pout_hs_w = (H_cnt >= I_h_sync + I_h_res && H_cnt < I_h_sync + I_h_res + I_h_bporch) ? 16'b1 : 16'b0;
        Pout_vs_w = (V_cnt >= I_v_sync && V_cnt < I_v_sync + I_v_res) ? 16'b1 : 16'b0;
        Rden_w = (H_cnt >= I_h_sync + I_h_res + I_h_bporch && H_cnt < I_h_sync + I_h_res + I_h_bporch + I_h_bporch) ? 16'b1 : 16'b0;
    end
    always @*
    begin
        O_rden <= Rden_w;
        O_de <= Pout_de_w;
        O_hs <= I_hs_pol ? Pout_hs_w : 16'b0;
        O_vs <= I_vs_pol ? Pout_vs_w : 16'b0;
    end
endmodule

