module pddm (
	input sdi, 
	input signed_data, 
	output [31:0] dout, 
	input ock, uck, 
	input rstn, clk
);
reg [31:0] sigma;
	reg [31:0] undersampled_sigma;
	reg [31:0] delta;
	wire [31:0] deriv;

	assign deriv = sigma - undersampled_sigma;

	always @(posedge clk or negedge rstn) begin
		if (!rstn) begin
			sigma <= 0;
			undersampled_sigma <= 0;
			delta <= 0;
		end else begin
			if (ock) begin
				if (sdi) begin
					sigma <= sigma + delta;
				end else begin
					sigma <= sigma - delta;
				end
			end
			if (uck) begin
				if (sdi) begin
					undersampled_sigma <= undersampled_sigma + delta;
				end else begin
					undersampled_sigma <= undersampled_sigma - delta;
				end
			end
		end
	end

	assign dout = (signed_data) ? {32{deriv[31]}}} : {32{deriv[31]}}, 32'd0};

	assign delta = (sdi) ? 32'd1 : 32'd-1;

endmodule

