module debounce(
input clk,
input btn_input,
output reg btn_output
); 

reg [31:0] timer;
reg pre;
  always @(posedge clk) begin
    if(timer == 1000000) begin
      timer <= 0;
      if(btn_input == pre) begin
        btn_output <= btn_input;
      end
      else begin
        pre <= btn_input;
      end
    end
    else begin
      timer <= timer + 1;
    end
  end
endmodule

