module dpram_async
#(
    parameter ADDR_WIDTH = 32,
    parameter DATA_WIDTH = 32,
    parameter CLEAR_ON_INIT = 1,
    parameter ENABLE_BYPASS = 1
)
(
    clk,
    rst,
    raddr,
    re,
    waddr,
    we,
    din,
    dout
);


input                           clk;
input                           rst;
input [ADDR_WIDTH-1:0]          raddr;
input                           re;
input [ADDR_WIDTH-1:0]          waddr;
input                           we;
input [DATA_WIDTH-1:0]          din;
output [DATA_WIDTH-1:0]         dout;
reg [DATA_WIDTH-1:0]             mem;
reg [DATA_WIDTH-1:0]             dout;

reg [DATA_WIDTH-1:0]             bypass;

initial begin
    if (CLEAR_ON_INIT) begin
        mem = 0;
    end
end

always @(*) begin
    bypass = mem[waddr];
end

always @(*) begin
    if (ENABLE_BYPASS) begin
        dout = bypass;
    end else begin
        dout = mem[raddr];
    end
end

always @(posedge clk) begin
    if (we) begin
        mem[waddr] <= din;
    end
end

endmodule

