module edge_detector (
    input wire clk,          
    input wire rst_n,        
    input wire signal_in,    
    output reg rising_out,   
    output reg falling_out   
);
reg signal_in_prev;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        signal_in_prev <= 1'b0;
        rising_out <= 1'b0;
        falling_out <= 1'b0;
    end else begin
        signal_in_prev <= signal_in;
        if (signal_in_prev == 1'b0 && signal_in == 1'b1) begin
            rising_out <= 1'b1;
            falling_out <= 1'b0;
        end else if (signal_in_prev == 1'b1 && signal_in == 1'b0) begin
            rising_out <= 1'b0;
            falling_out <= 1'b1;
        end else begin
            rising_out <= 1'b0;
            falling_out <= 1'b0;
        end
    end
end

