module adapter_rgb_2_ppfifo #(
  parameter                 DATA_WIDTH = 24
)(
  input                             clk,
  input                             rst,

  input         [23:0]              i_rgb,
  input                             i_h_sync,
  input                             i_h_blank,
  input                             i_v_sync,
  input                             i_v_blank,
  input                             i_data_en,


  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data


);
localparam IDLE = 2'b00;
  localparam READY = 2'b01;
  localparam RELEASE = 2'b10;

  reg [1:0] state;
  reg [31:0] r_count;

  assign o_ppfifo_clk = clk;
  assign o_ppfifo_act = state;
  assign o_ppfifo_stb = state == READY;
  assign o_ppfifo_data = i_rgb;

  always @(posedge clk) begin
    if (rst) begin
      state <= IDLE;
      r_count <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (i_ppfifo_rdy == 2'b11) begin
            state <= READY;
            o_ppfifo_act <= 2'b11;
          end
        end
        READY: begin
          if (i_h_blank) begin
            o_ppfifo_act <= 2'b00;
          end else if (i_v_blank) begin
            o_ppfifo_act <= 2'b10;
          end else if (i_data_en) begin
            o_ppfifo_stb <= 1'b1;
            o_ppfifo_data <= i_rgb;
            r_count <= r_count + 1;
          end else begin
            o_ppfifo_stb <= 1'b0;
          end
        end
        RELEASE: begin
          o_ppfifo_act <= 2'b00;
        end
      endcase
    end
  end

endmodule

