module data_deal(
	clk,
	rst_n,
	data_in,
	data_in_sign,

	data_out,
	data_out_sign,
	data_valid,
	data_ok
    );



	input 	clk;
	input 	rst_n;
	input 	[6:0]	data_in;
	input 	data_in_sign;

	output	[6:0]	data_out;
	output	data_out_sign;
	input 	data_valid;
	output	data_ok;
reg 	[6:0]	data_reg;
	reg 	data_regnum;
	reg 	data_out_sign;
	reg 	data_ok;

	always @ (negedge rst_n or posedge clk)
	begin
		if (!rst_n)
		begin
			data_reg <= 7'b0;
			data_regnum <= 0;
			data_out_sign <= 0;
			data_ok <= 0;
		end
		else
		begin
			if (data_in_sign)
			begin
				data_reg <= data_reg + data_in;
				data_regnum <= data_regnum + 1;
			end
			else
			begin
				data_reg <= data_reg;
				data_regnum <= data_regnum;
			end
			if (data_regnum == 8)
			begin
				if (data_reg == 28 || data_reg == 36)
				begin
					data_ok <= 1;
				end
				else
				begin
					data_ok <= 0;
				end
			end
			else
			begin
				data_ok <= 0;
			end
		end
	end

	always @ (data_valid or data_out)
	begin
		if (data_valid)
		begin
			data_out_sign <= 1;
			data_out <= data_out + 1;
		end
		else
		begin
			data_out_sign <= 0;
		end
	end
endmodule

module clk_div(
input wire clk_100MHz,
input wire reset,
output wire clk_100Hz
); 

reg clk_out;
reg [31:0] ticks;
  always @(posedge clk_100MHz, posedge reset) begin
    if(reset == 1'b1) begin
      ticks <= 499999;
      clk_out <= 1'b0;
    end else begin
      ticks <= ticks - 1;
      if(ticks == 0) begin
        clk_out <=  ~clk_out;
      end
    end
  end
  assign clk_100Hz = clk_out;
endmodule

