module counter_ex3(
input wire clk,
input wire clr,
input wire cnten,
output wire [15:0] q
); 

reg [15:0] cnt;
  always @(posedge clk, posedge clr, posedge cnten) begin
    if(clr == 1'b1) begin
      cnt <= 16'b0000000000000000;
    end else begin
      if(cnten == 1'b1) begin
        cnt <= cnt + 1;
        if(cnt == 16'b1111111111111111) begin
          cnt <= 16'b0000000000000000;
        end
      end
    end
  end
  assign q = cnt;
endmodule

