```module TopModule
  (
    .clk,
    .reset,
    .data,
    .start_shifting
  )
  ;
  reg [1:0] state;
  reg start_shifting;
  always @(posedge clk)
  begin
    if (reset)
      state <= 2'b00;
    else
      case (state)
        2'b00: begin
          if (data)
            state <= 2'b01;
          else
            state <= 2'b00;
        end
        2'b01: begin
          if (data)
            state <= 2'b10;
          else
            state <= 2'b00;
        end
        2'b10: begin
          if (data)
            state <= 2'b11;
          else
            state <= 2'b00;
        end
        2'b11: begin
          if (data)
            state <= 2'b00;
          else
            state <= 2'b11;
        end
        default: state <= 2'b00;
      endcase
  end
  always @(posedge clk)
  begin
    if (reset)
      start_shifting <= 1'b0;
    else
      case (state)
        2'b00: begin
          if (data)
            start_shifting <= 1'b1;
          else
            start_shifting <= 1'b0;
        end
        2'b01: begin
          if (data)
            start_shifting <= 1'b1;
          else
            start_shifting <= 1'b0;
        end
        2'b10: begin
          if (data)
            start_shifting <= 1'b1;
          else
            start_shifting <= 1'b0;
        end
        2'b11: begin
          if (data)
            start_shifting <= 1'b1;
          else
            start_shifting <= 1'b0;
        end
        default: start_shifting <= 1'b0;
      endcase
  end
