module TopModule;
reg [15:0] scancode;
wire left;
wire down;
wire right;
wire up;

always @ (scancode) begin
  case (scancode[15:0])
    16'he06b: begin
      left <= 1;
      down <= 0;
      right <= 0;
      up <= 0;
    end
    16'he072: begin
      left <= 0;
      down <= 1;
      right <= 0;
      up <= 0;
    end
    16'he074: begin
      left <= 0;
      down <= 0;
      right <= 1;
      up <= 0;
    end
    16'he075: begin
      left <= 0;
      down <= 0;
      right <= 0;
      up <= 1;
    end
    default: begin
      left <= 0;
      down <= 0;
      right <= 0;
      up <= 0;
    end
  endcase
end

endmodule
