  (clk, reset, in, out)
  ;
  localparam B = 0, A = 1;
  reg state, next_state;
  always @(posedge clk)
    state <= next_state;
  always @*
    case (state)
      B: if (in == 0)
          next_state = A;
        else
          next_state = B;
      A: if (in == 0)
          next_state = B;
        else
          next_state = A;
      default: next_state = B;
    endcase
  assign out = state;
