```module TopModule
  (
    .clk,
    .areset,
    .j,
    .k,
    .out
  )
  ;
  localparam OFF = 1'b0;
  localparam ON  = 1'b1;

  reg state;
  reg next_state;

  always @(posedge clk)
  begin
    if (areset)
      state <= OFF;
    else
      state <= next_state;
  end

  always @*
  begin
    next_state = state;
    case (state)
      OFF:
        begin
          if (j)
            next_state = OFF;
          else
            next_state = ON;
        end
      ON:
        begin
          if (k)
            next_state = ON;
          else
            next_state = OFF;
        end
      default:
        next_state = OFF;
    endcase
  end

  assign out = state;

endmodule
