  ;
  reg [11:0] clock;
  reg [1:0] ampm;
  always @(posedge clk)
    if (reset)
      clock <= 12;
    else if (ena)
      clock <= clock + 1;
  always @(posedge clk)
    if (reset)
      ampm <= 2'b00;
    else if (ena)
      ampm <= ampm + 1;
  assign pm = ampm[1];
  assign hh = clock[11:10];
  assign mm = clock[9:8];
  assign ss = clock[7:0];
endmodule
